rows=[
('Склеп','1: 5 брёвен + 5 камней + 500 монет; 2: 5 брёвен + 1 доска + 5 камней.','Зелёная краска = 1 грибная текила + 1000 монет; труба = 1 шестерня + 1 металл. Третья стадия в тексте источника не указана.'),
('Лестница в небо','1: 20 любви + 10 белого мрамора + 5 листов золота; 2: 80 любви + 30 белого мрамора + 15 флюгеров; 3: 150 любви + 30 стали + 20 огня.','Рулетка.'),
('Маяк','1: 30 брёвен + 20 камней + 2 зелёные краски; 2: 40 камней + 5 досок + 5 цемента; 3: 10 цемента + 3 супер-клея + 5 труб.','Красная краска = 1 клеверхелл + 1000 монет; проволока = 1 металл + 1 шестерня; ведро = 1 металл + 3 шестерни.'),
('Японский сад','1: 15 бруса секвойи + 25 мыла + 15 волчьего штыка; 2: 20 чёрного мрамора + 15 красной черепицы + 5 флюгеров; 3: 10 лампочек + 35 синей черепицы + 50 стекла.','Порох = 1 уголь + 1 кувалда; розовые нитки = 1 розовая краска + 1 канат; 2 зелёные нитки = 3 зелёных краски + 1 шляпка; жёлтые нитки = 3 жёлтых краски + 1 шерсть. Другая страница Zomboferma указывает 35 красной черепицы, не 15.'),
('Пирамида','1: 30 камней + 20 брёвен + 5 гипномака; 2: 100 камней + 10 досок + 10 труб; 3: 3 скотча + 10 цемента + 15 острой росянки.','Жёлтая краска = 1 хеллия + 1000 монет; гвозди = 1 проволока + 1 шестерня; блоки = 1 камень + 1000 монет; мрамор = 5 камней + 10 зелёной краски.'),
('Волшебный Кролик','1: 5 досок + 3 красной краски + 100 баклажанов; 2: 10 гвоздей + 5 зелёной краски + 50 бамбука; 3: 10 досок + 1 жёлтая краска + 10 труб; 4: 10 проволоки + 10 цемента + 10 стекла.','Металл = 1 шестерня + 500 монет; шестерня = 1 металл + 500 монет.'),
('Снеговик','1: 100 снежков + 10 цемента + 5000 монет; 2: 50 снежков + 30 цемента + 10 000 монет; 3: 15 снежков + 50 цемента + 30 000 монет.','Жёлтая краска = 1 супер-клей + 1 трансформатор; синяя черепица = 3 цемента + 15 черники с косточкой.'),
('Мельница','1: 30 брёвен + 20 камней + 10 досок; 2: 20 цемента + 10 проволок + 10 труб; 3: 20 красной краски + 10 жёлтой краски + 10 пружин.','Доска = 5 брёвен + 5000 монет; цемент = 5 камней + 5000 монет.'),
('Зомбоящик','1: 50 гипносолнухов + 20 черничных кренделей + 10 досок; 2: 50 баклажадин + 30 золотой пыли + 10 металла; 3: 50 кукурузных палочек + 10 стекла + 10 шестерни.','10 мгновенных удобрений = 2 черепка в томате + 1000 монет; 10 удобрений 30% = 1 грибная текила + 1 монета (буквально у источника; требует проверки).'),
('Китайская башня','1: 20 блоков + 5 досок + 1 канат; 2: 15 блоков + 4 бруса секвойи + 2 белых мрамора.','Зелёный пластилин = 5 зелёной краски + 20 еловых веток.'),
('Цветик','1: 50 досок + 10 зелёной краски + 2 супер-клея; 2: 30 проволок + 5 огня + 10 жёлтой краски; 3: 3 скотча + 50 красной краски + 5 воды.','В том же блоке источник ошибочно пишет «В пирамиде производится»: огонь = 5 любви + 10 чеснока; синяя черепица = 5 стекла + 5 любви. Связь рецептов с Цветиком требует сверки.'),
('Бассейн','1: 10 вёдер + 50 блоков + 10 проволоки; 2: 10 труб + 20 синей черепицы + 5 зелёной краски; 3: 20 досок + 30 снежков + 10 цемента.','Вода = 1 снежок + 1 огонь.'),
('Университет','1: 20 досок + 100 камней + 3 супер-клея; 2: 3 колоннады + 15 пружин + 4 флюгера.','Лист золота = 2 жёлтой краски + 2 металла; красная черепица = 1 красная краска + 1 синяя черепица.'),
('Глаз-алмаз','1: 50 блоков + 10 жёлтой краски + 10 цемента; 2: 100 блоков + 30 золотой пыли + 30 цемента; 3: 10 листов золота + 20 стекла + 5 трансформаторов.','5 супер-лопат = 10 бамбука + 2000 монет; 10 супер-лопат = 1 доска + 2 гвоздя.'),
('Вождь','1: 50 блоков + 50 проволоки + 50 досок; 2: 3 скотча + 10 листов золота + 30 пружин; 3: 100 шестерни + 50 стекла + 30 любви.','5 железных сердец = 10 любви + 1 трансформатор; 5 синих сердец = 15 любви + 1 трансформатор; огонь = 1 любовь + 1 железное сердце.'),
('На Альфу','1: 10 болтов + 10 гаек + 10 кирпичей; 2: 10 фанеры + 5 чернил + 20 чёрного мрамора; 3: 15 ваты + 15 пенопласта + 5 углеволокна.','Перемещает на остров Альфа.'),
('Нефтяная Вышка','1: 20 досок + 30 вёдер + 20 труб; 2: 20 пружин + 20 огня + 20 красной краски; 3: 10 брёвен + 20 любви + 100 бамбука.','5 нефти = 2 ведра + 2 трансформатора; чёрное сердце = 1 любовь + 1 нефть.'),
('Эйфелева башня','1: 15 чёрных + 15 синих + 15 железных сердец; 2: 30 мира + 80 металла + 30 мрамора; 3: 5 флюгеров + 10 проволоки + 15 жёлтой краски.','1 болт = 1 сталь + 5 чёрных рук; 1 пенопласт = 1 вата + 1 огонь.'),
('Пруд','1: 50 золотой пыли + 10 синего пластилина + 5 кафеля; 2: 15 колоннад + 10 красного пластилина + 5 зелёных ниток; 3: 10 пороха + 15 зелёного пластилина + 5 жёлтых ниток.','Золотая рыбка = 1 язь + 5 листов золота; шёлк = 1 лепесток розы + 1 розовая нитка; уголь = 1 мел + 1 нефть.'),
('Особняк','1: 50 блоков + 20 жёлтой краски + 10 цемента; 2: 20 мрамора + 30 красной черепицы + 1 супер-клей; 3: 10 листов золота + 10 стекла + 5 огня.','10 любви = 50 алых роз + 1 трансформатор или 20 лилий + 1 трансформатор.'),
('Белый Дом','1: 10 бруса секвойи + 50 любви + 20 огня; 2: 20 листов золота + 30 бруса секвойи + 10 блоков; 3: 13 синей черепицы + 13 нефти + 13 колоннад.','3 кварца = 10 стекла + 1 трансформатор; белая краска = 50 алых роз + 5 любви; зелёный мрамор = 10 блоков + 10 любви.'),
('Ракета','1: 20 стекла + 20 капель воды + 20 пружин; 2: 20 шестерни + 20 хеллии + 5 супер-клея; 3: 20 белой краски + 10 нефти + 10 огня.','Перемещает на секретный остров.'),
('Японский Храм','1: 50 белого мрамора + 100 брёвен пальмы + 10 японского гороха; 2: 20 чёрного мрамора + 10 бруса секвойи + 10 чесночных лилий; 3: 20 капель воды + 10 огня + 1 гипносон.','Бумага = 3 секвойи + 5 капель воды; брус секвойи = 3 секвойи + 1 шестерня; 2000 опыта = 100 любви + 2 трансформатора; мозги на день = 5 пороха + 1 жёлтый тюльпан.'),
('Останкино','1: 150 цемента + 50 проволоки + 80 стекла; 2: 30 кварца + 40 нефти + 10 флюгеров; 3: 150 любви + 150 мира + 2 волчиума.','Мозги на день = 2 хеллии + 10 любви или 1 глазная росянка + 10 любви.'),
('Сфинкс','1: 40 белого мрамора + 30 чёрного мрамора + 300 камней; 2: 20 блоков + 10 золотой пыли + 10 золиана; 3: 10 бумаги + 30 костяных ног + 5 чернил.','5 кирпичей = 15 цемента + 3 огня.'),
('Вавилон','1: 10 кирпичей + 5 стали + 30 секвойи; 2: 20 кирпичей + 10 брёвен пальмы + 100 бумаги; 3: 20 белого мрамора + 10 синей краски + 10 пенопласта; 4: 30 бруса секвойи + 10 розовой краски + 15 болтов; 5: 15 пенопласта + 10 углеволокна + 20 кварца; 6: 20 болтов + 20 стеклянных труб + 20 гаек; 7: 200 белых рук + 20 фанеры + 200 чёрных рук; 8: 30 углеволокна + 30 ваты + 50 золиана; 9: 300 тростника + 50 чернил + 300 капель воды.','Зомбакс = 500 000 монет + 1 зомбоксид (написание источника).'),
('АЭС','1: 45 кирпичей + 5 супер-клея + 50 капель воды; 2: 20 белого мрамора + 10 красной черепицы + 15 стали; 3: 15 фанеры + 5 трансформаторов + 50 любви.','Углеволокно = 10 чёрных рук + 5 ваты; стеклянная труба = 5 стекла + огонь.'),
('Ангар за монеты','1: 50 мира + 50 любви + 100 брёвен пальмы; 2: 30 кварца + 30 зелёного мрамора + 100 секвойи; 3: 5 пенопласта + 5 кирпичей + 10 фанеры.','Увеличение лимита принятия платных подарков на 5000 — по историческому источнику.'),
('Колизей','1: 100 времени + 5 кувалд + 30 капель воды; 2: 120 времени + 12 кувалд + 25 снежков; 3: 150 времени + 15 кувалд + 3 газеты.','Снежное дерево = 3 проволоки + 30 пряников; хижина = 5 стекла + 70 пряников; малый светильник = жёлтая краска + 10 пряников; большой светильник = 3 жёлтых краски = 25 пряников (в источнике знак равенства, требует сверки).'),
('Врата','1: 5 колоннад + 5 красной черепицы + 5 синей черепицы; 2: 5 зелёной краски = 5 красной краски + 5 жёлтой краски (знак равенства у источника); 3: 10 флюгеров + 10 супер-клея + 10 канатов; 4: по 10 железных, синих и чёрных сердец; 5: 15 компасов + 15 ваты + 10 бумаги; 6: 15 болтов + 15 гаек + 15 пенопласта; 7: 20 фанеры + 20 стеклянных труб + 20 кирпичей.','Белый мрамор = 4 пенопласта + 1 кувалда; чёрный мрамор = 4 пенопласта + 1 кувалда.')]
